-- BuildPulse cryptographic agility scaffolding. This does not itself implement or claim PQ E2EE.
alter table public.buildpulse_social_messages add column if not exists crypto_suite text not null default 'e2ee-v1';
alter table public.buildpulse_social_messages add column if not exists crypto_version integer not null default 1 check(crypto_version>0);
alter table public.buildpulse_social_messages add column if not exists sender_device_id uuid;
create table if not exists public.buildpulse_social_crypto_devices(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,device_label text,protocol_version integer not null default 1,identity_key_classical text,identity_key_pq text,kem_algorithm text,signature_algorithm text,key_version integer not null default 1,revoked_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.buildpulse_crypto_inventory(id uuid primary key default gen_random_uuid(),system_area text not null,crypto_purpose text not null,current_algorithm text,target_algorithm text,pq_status text not null default 'inventory' check(pq_status in ('inventory','planned','hybrid','pq','not_applicable')),owner text,risk_notes text,last_reviewed_at timestamptz not null default now(),unique(system_area,crypto_purpose));
